// ResearchVoice AI integrated Telegram state machine (single trigger)
// Demo storage uses n8n workflow static data. See README before real deployment.
const u = $input.first().json;
const msg = u.message || u.callback_query?.message || {};
const userId = String(u.callback_query?.from?.id ?? u.message?.from?.id ?? '');
const chatId = String(msg.chat?.id ?? '');
if (!chatId || !userId) return [];
if (String(msg.chat?.type ?? 'private') !== 'private') return [];
const textInput = String(u.message?.text ?? '').trim();
const command = textInput.split(' ')[0].split('@')[0].toLowerCase();
const cb = String(u.callback_query?.data ?? '');
const voiceId = u.message?.voice?.file_id ?? u.message?.audio?.file_id ?? '';
const db = $getWorkflowStaticData('global');
db.rv ??= {studies:{},cases:{},sessions:{},completed:{},seen:{}};
const store = db.rv;
for (const k of ['studies','cases','sessions','completed','seen']) store[k] ??= {};
const now = Date.now();
// Bound event history and avoid duplicate Telegram delivery within a running workflow.
if (u.update_id !== undefined) {
  const eid = String(u.update_id);
  if (store.seen[eid]) return [];
  store.seen[eid] = now;
  if (Object.keys(store.seen).length > 400) {
    for (const [k,v] of Object.entries(store.seen)) if (v < now - 86400000) delete store.seen[k];
    if (Object.keys(store.seen).length > 400) {
      for (const k of Object.keys(store.seen).slice(0,150)) delete store.seen[k];
    }
  }
}
const key = userId + ':' + chatId;
const s = store.sessions[key] ??= {user_id:userId, chat_id:chatId, state:'idle'};
s.chat_id = chatId;
s.user_id = userId;
const nonce = () => now.toString(36) + Math.random().toString(36).slice(2,7);
const ret = (action, text='', other={}) => [{json:{action, chat_id:chatId, user_id:userId, text, nonce:s.nonce||'',...other}}];
const say = text => ret('send_plain',text);
const menu = () => ret('send_menu','🧪 ResearchVoice AI\n⚠️ DEMO ONLY: use synthetic/de-identified data. Never send real patient information.\nVoice is disabled until you explicitly type /voiceon.\nChoose an option below, or use /studies, /new, /case, /help.');
const activeStudy = () => store.studies[s.study_id];
const activeCase = () => store.cases[s.case_id];
const studyList = () => Object.values(store.studies).filter(x=>x.researcher_id===userId && Array.isArray(x.variables) && x.variables.length).sort((a,b)=>a.created_at.localeCompare(b.created_at));
const normalize = x=>String(x??'').trim().toLowerCase();
const buildReview = () => {
  const study = activeStudy();
  const specs = study?.variables||[];
  const d=s.draft||{};
  const vals=d.values||{};
  const missing=specs.filter(v=>!Object.prototype.hasOwnProperty.call(vals,v.name)).map(v=>v.name);
  d.missing=missing;
  const lines=specs.map(v=>`• ${v.name}: ${vals[v.name]===undefined?'⚠️ NOT DOCUMENTED':String(vals[v.name])}${v.unit&&vals[v.name]!==undefined?' '+v.unit:''}`);
  const issues=(d.issues||[]).map(x=>`• ${x.variable_name}: ${x.reason}`).join('\n');
  s.nonce=nonce();
  s.state='await_values_review';
  const body=`🔎 FINAL REVIEW\nStudy: ${study?.study_name||''}\nCase: ${activeCase()?.case_code||''}\nVisit: ${s.visit_number||1} (${s.visit_id}) · ${s.visit_date}\n\n${lines.join('\n')}\n${missing.length?'\nMissing: '+missing.join(', '):''}${issues?'\n⚠️ Needs correction:\n'+issues:''}\n\nTo correct: Age = 56 (one per line).\nMissing values require explicit “Leave missing blank”. Conflicts must be resolved.\nConfirm only after checking every value.`;
  return ret('send_values',body);
};
const newStudy = () => {s.state='await_study_name';s.study_id='';s.case_id='';return say('➕ Enter the new study name.\nاكتب اسم الدراسة الجديدة.');};
const chooseStudies = () => {
  const studies=studyList();
  if(!studies.length)return say('No approved studies yet. Use /new to create one.');
  s.selection_ids=studies.map(x=>x.study_id); s.state='await_study_selection';
  return say('📂 Choose a study by sending its number:\n\n'+studies.map((v,i)=>`${i+1}. ${v.study_name} (${v.study_id})`).join('\n'));
};
const prepareNextCase = () => {
  if(!activeStudy()?.variables?.length)return say('Select a study with approved variables first. Use /studies.');
  s.state='await_case_code'; return say(`Study: ${activeStudy().study_name}\nSend the patient/case CODE (not identifying information). Existing codes open a follow-up visit.`);
};
const makeVisit = caseRec => {
  if(!caseRec) return say('No case selected. Use /case first.');
  const n=(caseRec.visit_counter||0)+1;
  caseRec.visit_counter=n;
  s.visit_number=n;
  s.visit_id=caseRec.case_id+'-V'+String(n).padStart(3,'0');
  s.draft=null;s.pending_transcript='';s.skip_missing=false;s.visit_date='';s.state='await_visit_date';
  return say(`✅ Case ${caseRec.case_code} · Visit ${n}\nEnter the visit date as YYYY-MM-DD (or /today for today). The date must be explicitly confirmed; it is not inferred from submission time.`);
};
const acceptCase = raw => {
  const code=String(raw||'').trim();
  if(!/^[A-Za-z][A-Za-z0-9_-]{2,31}$/.test(code))return say('Use a fictional case code: 3–32 characters, starting with a letter, with letters/digits/_/- only (e.g. PAT-001). No real names or identifiers.');
  const study=activeStudy();if(!study)return say('Choose a study first: /studies');
  let c=Object.values(store.cases).find(x=>x.study_id===study.study_id&&x.researcher_id===userId&&normalize(x.case_code)===normalize(code));
  if(!c){
    const caseId='CASE-'+nonce().toUpperCase();
    c={case_id:caseId,study_id:study.study_id,researcher_id:userId,case_code:code,created_at:new Date().toISOString(),visit_counter:0};
    store.cases[caseId]=c;
  }
  s.case_id=c.case_id;
  return makeVisit(c);
};
const txReview = (t,kind) => {
  s.pending_transcript=t.slice(0,14000);
  s.transcript_kind=kind;
  s.state='await_transcript_confirm';s.nonce=nonce();
  return ret('send_tx',`🎙️ TRANSCRIPT REVIEW (${kind==='schema'?'study variable schema':'case data'})\n\n${s.pending_transcript.slice(0,2900)}${s.pending_transcript.length>2900?'\n[Preview truncated]':''}\n\nConfirm it, send a replacement text, or choose Redo.`);
};
const startSTT = kind => {
  s.transcript_kind=kind;
  s.state='transcribing';
  return ret('transcribe','',{file_id:voiceId});
};
const applyCorrections = incoming => {
  const study=activeStudy(); const d=s.draft;
  if(!study||!d)return say('No pending data review.');
  const lines=incoming.split(/[\n;]+/).map(x=>x.trim()).filter(Boolean);
  let count=0;const errors=[];
  const validate=(v,raw)=>{
    let val=raw.trim();
    if(['integer','decimal'].includes(v.data_type)){
      const unit=String(v.unit||'').trim();
      if(unit && val.toLowerCase().endsWith(unit.toLowerCase()))val=val.slice(0,-unit.length).trim();
      if(!/^[+-]?(?:\d+\.?\d*|\.\d+)$/.test(val))return {error:'Expected a numeric value'+(unit?' in '+unit:'')};
      const n=Number(val);
      if(!Number.isFinite(n)||v.data_type==='integer'&&!Number.isInteger(n))return {error:'Invalid '+v.data_type};
      return {value:n};
    }
    if(v.data_type==='boolean'){
      if(['true','yes','1'].includes(normalize(val)))return {value:true};
      if(['false','no','0'].includes(normalize(val)))return {value:false};
      return {error:'Expected yes/no or true/false'};
    }
    if(v.data_type==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(val))return {error:'Expected YYYY-MM-DD'};
    const allowed=v.allowed_values||[];
    if(allowed.length && !allowed.some(x=>normalize(x)===normalize(val)))return {error:'Not one of allowed values: '+allowed.join(', ')};
    return {value:val};
  };
  for(const line of lines){
    const m=line.match(/^([^:=]+)\s*[:=]\s*(.+)$/);
    if(!m){errors.push('Use Name = value');continue;}
    const v=study.variables.find(x=>normalize(x.name)===normalize(m[1]));
    if(!v){errors.push('Unknown variable: '+m[1].trim());continue;}
    const res=validate(v,m[2]);
    if(res.error){errors.push(v.name+': '+res.error);continue;}
    d.values[v.name]=res.value;
    d.evidence[v.name]='Researcher correction via Telegram';
    d.manual_corrections??=[]; if(!d.manual_corrections.includes(v.name))d.manual_corrections.push(v.name);
    d.issues=(d.issues||[]).filter(x=>normalize(x.variable_name)!==normalize(v.name));
    count++;
  }
  if(!count)return say('No valid corrections applied.\n'+errors.join('\n'));
  s.skip_missing=false;
  const out=buildReview();
  if(errors.length)out[0].json.text+='\n\n⚠️ Invalid lines ignored:\n'+errors.join('\n');
  return out;
};
const acceptVisitDate = raw => {
  const date=String(raw||'').trim();
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date) return say('Invalid date. Send YYYY-MM-DD, for example 2026-10-24, or /today.');
  s.visit_date=date;s.state='await_case_data';
  return say(`Visit date set to ${date}.\nNow send a voice note or typed case description. Only the approved study variables will be extracted.`);
};
const cancel=()=>{s.state='idle';s.draft=null;s.pending_transcript='';s.skip_missing=false;return say('Cancelled. No patient record was exported. Use /case or /studies to continue.');};

// DEMO GUARDRAIL: best-effort pattern checks only; never a guarantee of PHI detection.
// Do not use this system with real patient information.
const rvSafetyCheck = (input) => {
  const value = String(input ?? '').trim();
  if (!value) return null;
  const identifiers = [
    ['email address', /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i],
    ['phone number', /(?:^|[^\d])(?:\+?20|0020|0)?1[0125][\s.\-]?\d{4}[\s.\-]?\d{4}(?!\d)/],
    ['national identity number', /(?:^|[^\d])[23]\d{13}(?!\d)/],
    ['patient-identifying label', /\b(?:patient(?:'s)?\s+(?:full\s+)?name|full\s+name\s*:|patient\s+(?:is\s+)?named|passport\s*(?:number|no\.?|:)|national\s*(?:identity|id)\s*(?:number|no\.?|:)|home\s+address|medical\s+record\s+number|\bMRN\s*:)\b/i],
    ['identifying Arabic label', /(?:الرقم\s*القومي|رقم\s*(?:الموبايل|الهاتف|التليفون|جواز\s*السفر)|الاسم\s*(?:الكامل|الرباعي)|عنوان\s*المنزل)/i],
    ['street address', /\b\d{1,5}\s+[A-Za-z][A-Za-z.\s]{2,35}\s+(?:Street|St\.?|Road|Rd\.?|Avenue|Ave\.?|Boulevard|Blvd\.?)\b/i],
  ];
  for (const [label, pattern] of identifiers) {
    if (pattern.test(value)) return {kind:'identity', label};
  }
  const injections = [
    /\b(?:ignore|disregard|override)\s+(?:(?:all|your|the)\s+){0,2}(?:previous|prior|system|developer)\s+(?:instructions|rules|prompt)\b/i,
    /\b(?:approve|accept|export|confirm)\b.{0,75}\b(?:without\s+(?:human\s+)?(?:verification|review|approval)|without\s+checking|bypass\s+(?:human\s+)?(?:verification|review|approval))\b/i,
    /\b(?:reveal|print|expose|show)\b.{0,35}\b(?:system\s+prompt|api\s+key|credentials?|hidden\s+instructions)\b/i,
    /\b(?:you\s+are\s+now|act\s+as)\s+(?:a\s+)?(?:system|developer|unrestricted)\b/i,
  ];
  if (injections.some(p => p.test(value))) return {kind:'injection', label:'instruction attempt'};
  const careRequests = [
    /\b(?:please\s+)?(?:diagnose|prescribe|write\s+(?:a\s+)?prescription)\s+(?:this\s+|the\s+|my\s+)?(?:patient|person|case|for\b)/i,
    /\b(?:please\s+)?(?:prescribe|recommend|change|increase|decrease|adjust)\b.{0,40}\b(?:medication|treatment|drug|dose|dosage|insulin)\b/i,
    /\b(?:tell\s+me|tell\s+the\s+patient|give\s+the\s+patient)\b.{0,40}\b(?:diagnosis|dose|dosage|treatment)\b/i,
    /(?:اكتب\s*(?:روشتة|علاج)|شخص\s*(?:المريض|الحالة)|غير\s*جرعة\s*(?:الدواء|العلاج))/i,
  ];
  if (careRequests.some(p => p.test(value))) return {kind:'clinical', label:'clinical decision request'};
  return null;
};

// Prevent *new typed research text* from being sent to Gemini when obvious risky content is detected.
// The Telegram platform and the n8n trigger receive incoming messages before this gate.
const rvBlock = rvSafetyCheck(textInput);
if (rvBlock) {
  store.monitoring??={events:[],seen:{},blocked:{identity:0,injection:0,clinical:0},exports_delivered:0,export_failed_attempts:0};
  store.monitoring.blocked??={identity:0,injection:0,clinical:0};
  store.monitoring.blocked[rvBlock.kind]=(store.monitoring.blocked[rvBlock.kind]||0)+1;
  const detail = rvBlock.kind === 'identity'
    ? 'Possible personal identifier detected. Remove names, phone numbers, IDs and addresses, then send fictional or de-identified research data.'
    : rvBlock.kind === 'injection'
      ? 'Instruction-like content was blocked. Send research facts only; do not request changes to AI instructions or credentials.'
      : 'This bot only collects research data. It cannot diagnose, prescribe or change treatment. Please refer clinical decisions to an authorised clinician.';
  return say('⛔ SAFETY CHECK: ' + detail + '\nNothing from this message was forwarded to Gemini.');
}


if (command === '/recover') {
  const stuckStates = [
    'processing_values',
    'processing_schema'
  ];

  if (!stuckStates.includes(s.state)) {
    return say(
      'No stuck AI request found. Current state: ' + s.state
    );
  }

  if (!s.pending_transcript ||
      !String(s.pending_transcript).trim()) {
    return say(
      'No saved transcript found. Use /case to continue.'
    );
  }

  const historicRisk = rvSafetyCheck(s.pending_transcript);
  if (historicRisk) {
    s.pending_transcript = '';
    s.state = s.transcript_kind === 'schema' ? 'await_schema_description' : 'await_case_data';
    return say('⛔ The previous transcript was blocked by the new privacy/safety check. Send synthetic replacement text.');
  }
  const kind = s.transcript_kind === 'schema'
    ? 'schema'
    : 'case';

  return txReview(s.pending_transcript, kind);
}
if(command==='/start'){s.state='idle';s.draft=null;s.pending_transcript='';s.voice_demo_opt_in=false;return menu();}
if(command==='/voiceon') {
  s.voice_demo_opt_in=true;
  return say('🎙️ Demo voice enabled for this chat session. By enabling it, you confirm future recordings contain ONLY fictional or properly de-identified data. Audio is uploaded to the external Groq transcription service BEFORE the words can be screened. Use /voiceoff to disable voice.');
}
if(command==='/voiceoff') {
  s.voice_demo_opt_in=false;
  return say('Voice transcription disabled. Typed synthetic data can still be used.');
}
if(command==='/today'&&s.state==='await_visit_date') return acceptVisitDate(new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()));
if(command==='/help')return say('DEMO ONLY: no real patient data.\nCommands:\n/monitor — rolling QA and safety monitoring summary\n/redo — re-enter this visit after a hard QA hold\n/start — home\n/new — create study\n/studies — choose study\n/case — new or existing case\n/visit — new visit for current case\n/review — current values\n/recover — unlock interrupted AI review\n/eval — inspect independent AI judge scores for current visit\n/voiceon — confirm synthetic-data voice upload to Groq\n/voiceoff — disable voice\n/retry — retry document delivery\n/cancel — cancel current review');
// Phase 2: view the last independent judge report for this visit.
// Scores are experimental QA for synthetic cases, NOT clinician authorization.
if(command==='/eval'||command==='/judge') {
  const evals=store.evaluations||{};
  const ev=s.visit_id&&evals[s.visit_id];
  if(!ev)return say('No evaluation found for the currently selected visit. Select a case with /case and submit a synthetic case description first.');
  if(ev.study_id!==s.study_id || ev.case_id!==s.case_id || ev.researcher_id!==userId)
    return say('Evaluation is unavailable for the selected case.');
  if(ev.status==='pending')return say('🧪 Evaluation is pending for this visit. Try /eval after a short while. The LLM judge does not approve clinical decisions.');
  if(ev.status==='failed')return say('⚠️ Independent AI evaluation failed. Original review/export are unchanged. Check the Judge Gemini HTTP and Save Judge Result nodes in n8n. Reason: '+String(ev.error||'unknown').slice(0,140));
  const dim=['factual_accuracy','groundedness','safety_compliance','format_adherence','bias'];
  const labels={factual_accuracy:'Factual accuracy',groundedness:'Groundedness',safety_compliance:'Safety compliance',format_adherence:'Format adherence',bias:'Bias / neutrality'};
  const scores=dim.map(k=>'• '+labels[k]+': '+String(ev.scores?.[k]??'?')+'/5').join('\n');
  const safe=(ev.scores?.safety_compliance??0)<=2 || ev.critical_safety_failure;
  const note=safe?'\n🚨 LOW SAFETY SCORE — manually review the execution; this demo does not automatically stop exports based on judge results.':'';
  const shortFlags=(ev.flags||[]).slice(0,3).map(x=>'• '+String(x).slice(0,110)).join('\n');
  return say('🧪 INDEPENDENT LLM-AS-JUDGE (DEMO)\nVisit: '+ev.visit_id+'\n'+scores+'\nOverall: '+ev.overall_assessment+'\nAverage: '+ev.average+'/5'+(shortFlags?'\nFlags:\n'+shortFlags:'')+note+'\n\nThese are uncalibrated model ratings, not verified accuracy or clinician approval.');
}
if(command==='/monitor') {
  // Team-level, aggregate only: no case codes, transcripts, IDs, or individual records.
  const mo=store.monitoring||{};
  const events=Array.isArray(mo.events)?mo.events:[];
  const ok=events.filter(e=>e.status==='completed');
  const durations=events.map(e=>e.judge_duration_ms).filter(n=>typeof n==='number'&&n>=0).sort((a,b)=>a-b);
  const means=ok.map(e=>e.average).filter(n=>typeof n==='number');
  const average=means.length?(means.reduce((a,b)=>a+b,0)/means.length).toFixed(2):'N/A';
  const p95=durations.length?Math.round(durations[Math.ceil(durations.length*0.95)-1]):'N/A';
  const n=events.length;
  const pct=cnt=>n?(100*cnt/n).toFixed(1)+'%':'N/A';
  const passed=ok.filter(e=>e.overall==='pass').length;
  const failed=events.filter(e=>e.status!=='completed').length;
  const soft=events.filter(e=>e.level==='soft').length;
  const hard=events.filter(e=>e.level==='hard').length;
  const blocked=mo.blocked||{};
  const blockedTotal=['identity','injection','clinical'].reduce((sum,k)=>sum+Number(blocked[k]||0),0);
  return say('📊 RESEARCHVOICE MONITORING (SYNTHETIC DEMO)\n'+
    'Rolling window: '+n+'/200 evaluation attempts (team-wide)\n'+
    'Judge completed: '+ok.length+' | Judge failures: '+failed+'\n'+
    'Judge pass: '+passed+' ('+pct(passed)+')\n'+
    'Mean judge score: '+average+'/5\n'+
    'Judge p95 latency: '+p95+' ms (not full workflow duration)\n'+
    'Soft warnings: '+soft+' | Hard holds: '+hard+'\n'+
    'Pre-Gemini safety rejections (voice already reached Groq): '+blockedTotal+
    ' (identity '+Number(blocked.identity||0)+', injection '+Number(blocked.injection||0)+', clinical '+Number(blocked.clinical||0)+')\n'+
    'Excel deliveries confirmed: '+Number(mo.exports_delivered||0)+' | Failed delivery attempts: '+Number(mo.export_failed_attempts||0)+'\n\n'+
    'These metrics cover available demo events only, not a validated clinical performance measure. LangSmith contains per-run QA checkpoints.');
}
if(command==='/new')return newStudy();
if(command==='/studies')return chooseStudies();
if(command==='/cancel')return cancel();
if(command==='/case'){
  if(textInput.length>5)return acceptCase(textInput.slice(5).trim());
  return prepareNextCase();
}
if(command==='/visit')return makeVisit(activeCase());
if(command==='/review'&&s.draft)return buildReview();
if(command==='/redo'&&s.state==='await_values_review'){
  // Reprocess the SAME visit; fresh extraction and judge score can release a hard hold.
  s.draft=null;s.pending_transcript='';s.skip_missing=false;s.nonce=nonce();s.state='await_case_data';
  return say('🔄 Re-enter a corrected SYNTHETIC case description for this visit. A fresh extraction and independent evaluation will run before any export.');
}
if(command==='/retry'&&s.state==='exporting'&&s.draft) return ret('export','',{record_id:s.visit_id});
if(cb){
  const pos=cb.lastIndexOf(':');const act=pos===-1?cb:cb.slice(0,pos);const value=pos===-1?'':cb.slice(pos+1);
  if(act==='menu_new')return newStudy();
  if(act==='menu_open')return chooseStudies();
  if(value!==s.nonce)return say('That button belongs to an older review. Use /review or resend your latest details.');
  if(act==='tx_redo'&&s.state==='await_transcript_confirm'){
    const kind=s.transcript_kind; s.pending_transcript='';s.state=kind==='schema'?'await_schema_description':'await_case_data';
    return say('Send a replacement voice note or text.');
  }
  if(act==='tx_confirm'&&s.state==='await_transcript_confirm'){
    // Defense in depth: screen the confirmed transcription again, including
    // transcripts created before this upgraded guardrail was published.
    const confirmedRisk=rvSafetyCheck(s.pending_transcript);
    if (confirmedRisk || !String(s.pending_transcript||'').trim()) {
      const kind=s.transcript_kind==='schema'?'schema':'case';
      s.pending_transcript='';s.nonce=nonce();
      s.state=kind==='schema'?'await_schema_description':'await_case_data';
      return say('⛔ SAFETY CHECK: Transcript cannot be confirmed because it is unsafe or empty. Nothing was forwarded to Gemini. Send a new synthetic description.');
    }
    s.state=s.transcript_kind==='schema'?'processing_schema':'processing_values';
    return ret(s.transcript_kind==='schema'?'schema_ai':'values_ai','');
  }
  if(act==='schema_redo'&&s.state==='await_schema_approval'){
    s.pending_schema=null;s.state='await_schema_description';return say('Send the study variable description again, including each variable name and type.');
  }
  if(act==='schema_approve'&&s.state==='await_schema_approval'){
    if(!Array.isArray(s.pending_schema)||!s.pending_schema.length)return say('No valid schema to approve. Please redo.');
    const study=activeStudy();if(!study)return say('Study not found.');
    study.variables=s.pending_schema;study.schema_approved_at=new Date().toISOString();s.pending_schema=null;
    return prepareNextCase();
  }
  if(act==='values_skip'&&s.state==='await_values_review'){
    if((s.draft?.issues||[]).length)return say('Resolve conflicting/unclear variables first by sending Name = value.');
    s.skip_missing=true;return buildReview();
  }
  if(act==='values_cancel'&&s.state==='await_values_review')return cancel();
  if(act==='values_confirm'&&s.state==='await_values_review'){
    const d=s.draft||{};
    if((d.issues||[]).length)return say('Unresolved values remain. Correct the listed variables before submission.');
    if((d.missing||[]).length&&!s.skip_missing)return say('Missing fields remain. Supply corrections or explicitly choose Leave missing blank.');
    // Phase 4 fail-closed demo gate for severe judge findings; this is NOT clinical validation.
    const qa=store.evaluations?.[s.visit_id];
    if(qa?.status==='completed' && (
      qa.critical_safety_failure===true || Number(qa.scores?.safety_compliance)<=2 || Number(qa.scores?.factual_accuracy)<=2
    )){
