const rvSafetyCheck = (input) => {
  const value = String(input ?? '').trim();
  if (!value) return null;
  const identifiers = [
    ['email address', /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i],
    ['phone number', /(?:^|[^\d])(?:\+?20|0020|0)?1[0125][\s.\-]?\d{4}[\s.\-]?\d{4}(?!\d)/],
    ['national identity number', /(?:^|[^\d])[23]\d{13}(?!\d)/],
    ['patient-identifying label', /\b(?:patient(?:'s)?\s+(?:full\s+)?name|full\s+name\s*:|patient\s+(?:is\s+)?named|passport\s*(?:number|no\.?|:)|national\s*(?:identity|id)\s*(?:number|no\.?|:)|home\s+address|medical\s+record\s+number|\bMRN\s*:)\b/i],
    ['identifying Arabic label', /(?:الرقم\s*القومي|رقم\s*(?:الموبايل|الهاتف|التليفون|جواز\s*السفر)|الاسم\s*(?:الكامل|الرباعي)|عنوان\s*المنزل)/i],
    ['street address', /\b\d{1,5}\s+[A-Za-z][A-Za-z.\s]{2,35}\s+(?:Street|St\.?|Road|Rd\.?|Avenue|Ave\.?|Boulevard|Blvd\.?)\b/i],
  ];
  for (const [label, pattern] of identifiers) {
    if (pattern.test(value)) return {kind:'identity', label};
  }
  const injections = [
    /\b(?:ignore|disregard|override)\s+(?:(?:all|your|the)\s+){0,2}(?:previous|prior|system|developer)\s+(?:instructions|rules|prompt)\b/i,
    /\b(?:approve|accept|export|confirm)\b.{0,75}\b(?:without\s+(?:human\s+)?(?:verification|review|approval)|without\s+checking|bypass\s+(?:human\s+)?(?:verification|review|approval))\b/i,
    /\b(?:reveal|print|expose|show)\b.{0,35}\b(?:system\s+prompt|api\s+key|credentials?|hidden\s+instructions)\b/i,
    /\b(?:you\s+are\s+now|act\s+as)\s+(?:a\s+)?(?:system|developer|unrestricted)\b/i,
  ];
  if (injections.some(p => p.test(value))) return {kind:'injection', label:'instruction attempt'};
  const careRequests = [
    /\b(?:please\s+)?(?:diagnose|prescribe|write\s+(?:a\s+)?prescription)\s+(?:this\s+|the\s+|my\s+)?(?:patient|person|case|for\b)/i,
    /\b(?:please\s+)?(?:prescribe|recommend|change|increase|decrease|adjust)\b.{0,40}\b(?:medication|treatment|drug|dose|dosage|insulin)\b/i,
    /\b(?:tell\s+me|tell\s+the\s+patient|give\s+the\s+patient)\b.{0,40}\b(?:diagnosis|dose|dosage|treatment)\b/i,
    /(?:اكتب\s*(?:روشتة|علاج)|شخص\s*(?:المريض|الحالة)|غير\s*جرعة\s*(?:الدواء|العلاج))/i,
  ];
  if (careRequests.some(p => p.test(value))) return {kind:'clinical', label:'clinical decision request'};
  return null;
};

